 auto p=sm::relativeLightPosition({light->Position.x,light->Position.y,light->Position.z},l.worldOrigin);auto i=l.sceneLampCount++;l.sceneLampIds[i]=id;l.sceneLamps[i]={{p.x,p.y,p.z,light->Range},{light->Diffuse.r,light->Diffuse.g,light->Diffuse.b,1},{light->Attenuation0,light->Attenuation1,light->Attenuation2,0}};return true;
