extern "C" bool StormMetalResolveLandLighting(void*pointer){
 if(!pointer)return false;auto*d=static_cast<Device*>(static_cast<IDirect3DDevice9*>(pointer));if(!d->landShadow.enabled||!d->landShadow.locationActive)return false;if(d->landShadow.prepass.frame)return d->landShadow.applied;if(d->landShadow.resolved)return d->landShadow.applied;
 if(d->target!=d->back||d->zbuffer!=d->depth||!d->command||!d->enabled[0]||d->lights[0].Type!=D3DLIGHT_DIRECTIONAL){d->landShadow.resolved=true;return false;}
 auto&sun=d->lights[0];simd_float3 direction={sun.Direction.x,sun.Direction.y,sun.Direction.z};if(simd_length(direction)<.001f){d->landShadow.resolved=true;return false;}simd_float4x4 view;memcpy(&view,&d->matrices[D3DTS_VIEW],64);d->finish();
